import 'package:encrypt/encrypt.dart';

/// SECURITY WARNING / KNOWN RISK:
/// This class ships an encrypted Service Account inside the client app, but the
/// AES key and IV are hardcoded right below. Anyone who decompiles the APK can
/// recover the credentials and bypass ALL Firebase security rules.
/// This is obfuscation, NOT real protection.
///
/// TODO(critical): Move push-notification sending to a server-side component
/// (e.g. Firebase Cloud Functions) and DELETE this class from the client.
/// It is kept as-is for now because [PushNotificationService] depends on it,
/// and removing it without a backend replacement would break push notifications.
class SecureServiceAccount {
  static const String _encryptedData = '';
  static const String _keyBase64 = 'MJSQn357z7KVYkUogVzpKIBqRwLQdKl5jZ3wFJmHtdM=';
  static const String _ivBase64 = 'I00XeuxSZvqSpE58uwN0gg==';

  static String getDecryptedJson() {
    final key = Key.fromBase64(_keyBase64);
    final iv = IV.fromBase64(_ivBase64);
    final encrypter = Encrypter(AES(key, mode: AESMode.cbc));
    
    return encrypter.decrypt64(_encryptedData, iv: iv);
  }
}
